import{_ as r,C as a,o as t,c as i,a3 as n,b as o,w as s,a as d,E as u,a4 as c}from"./chunks/framework.C8wZ88_B.js";const q=JSON.parse(`{"title":"Séance 1 — Ce qu'il faut pour mettre un site en ligne","description":"","frontmatter":{"title":"Séance 1 — Ce qu'il faut pour mettre un site en ligne","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/01-mettre-un-site-en-ligne.md","filePath":"modules/01-faisabilite/01-mettre-un-site-en-ligne.md"}`),g={name:"modules/01-faisabilite/01-mettre-un-site-en-ligne.md"};function p(f,e,h,m,x,b){const l=a("Mermaid");return t(),i("div",null,[e[1]||(e[1]=n('<h1 id="seance-1-—-ce-qu-il-faut-pour-mettre-un-site-en-ligne" tabindex="-1">Séance 1 — Ce qu&#39;il faut pour mettre un site en ligne <a class="header-anchor" href="#seance-1-—-ce-qu-il-faut-pour-mettre-un-site-en-ligne" aria-label="Permalink to &quot;Séance 1 — Ce qu&#39;il faut pour mettre un site en ligne&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Nommer les ressources techniques nécessaires pour mettre un site en ligne.</li><li>Expliquer le rôle de chacune dans le trajet d&#39;une page Web.</li><li>Distinguer ce qu&#39;on paie une seule fois de ce qu&#39;on paie chaque année.</li><li>Reconnaître les trois sortes de contraintes d&#39;un projet : techniques, organisationnelles et de ressources.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Accroche — Combien coûte ce site ?</td></tr><tr><td style="text-align:left;">18 h 45</td><td style="text-align:left;">Présentation du cours</td></tr><tr><td style="text-align:left;">19 h 00</td><td style="text-align:left;">Activité — Le trajet d&#39;une page Web, puis retour en groupe</td></tr><tr><td style="text-align:left;">19 h 40</td><td style="text-align:left;">Les ressources techniques et les trois sortes de contraintes</td></tr><tr><td style="text-align:left;">20 h 00</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 15</td><td style="text-align:left;"><a href="./../../labs/lab01-enquete-technique">Lab 01 — Enquête technique</a> (en duo)</td></tr><tr><td style="text-align:left;">21 h 45</td><td style="text-align:left;">Mise en commun</td></tr></tbody></table><hr><h2 id="accroche-—-combien-coute-ce-site" tabindex="-1">Accroche — Combien coûte ce site ? <a class="header-anchor" href="#accroche-—-combien-coute-ce-site" aria-label="Permalink to &quot;Accroche — Combien coûte ce site ?&quot;">​</a></h2><p>Trois restaurants ont un site Web. Pour chacun, estimez :</p><ol><li><strong>combien</strong> il a coûté à construire ;</li><li><strong>combien de temps</strong> il a fallu ;</li><li><strong>combien de personnes</strong> y ont travaillé ;</li><li><strong>combien</strong> il coûte <strong>chaque année</strong> pour rester en ligne.</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:left;">Restaurant</th><th style="text-align:left;">Ce que fait le site</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>A</strong></td><td style="text-align:left;">Un café de quartier</td><td style="text-align:left;">Une page : photos, heures d&#39;ouverture, adresse, lien vers Facebook</td></tr><tr><td style="text-align:center;"><strong>B</strong></td><td style="text-align:left;">Un bistro gastronomique</td><td style="text-align:left;">Plusieurs pages, menu mis à jour chaque saison, réservation en ligne, bilingue</td></tr><tr><td style="text-align:center;"><strong>C</strong></td><td style="text-align:left;">Une chaîne de 60 restaurants</td><td style="text-align:left;">Commande en ligne, programme de fidélité, compte client, application mobile, localisateur de succursales</td></tr></tbody></table><details class="mb-5"><summary><strong>Ordres de grandeur</strong> (à ouvrir après la discussion)</summary><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:left;">Construction</th><th style="text-align:left;">Délai</th><th style="text-align:left;">Équipe</th><th style="text-align:left;">Chaque année</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>A</strong></td><td style="text-align:left;">0 $ à quelques centaines de dollars (fait soi-même avec Wix, Squarespace…)</td><td style="text-align:left;">Une fin de semaine</td><td style="text-align:left;">1 personne, souvent la propriétaire</td><td style="text-align:left;">Quelques centaines de dollars (abonnement + nom de domaine)</td></tr><tr><td style="text-align:center;"><strong>B</strong></td><td style="text-align:left;">Quelques milliers à ~15 000 $ (pigiste ou petite agence, souvent WordPress)</td><td style="text-align:left;">Quelques semaines</td><td style="text-align:left;">1 à 3 personnes</td><td style="text-align:left;">Quelques centaines à quelques milliers de dollars (hébergement, extensions, entretien, réservation)</td></tr><tr><td style="text-align:center;"><strong>C</strong></td><td style="text-align:left;">Des dizaines, voire des centaines de milliers de dollars (agence, développement sur mesure)</td><td style="text-align:left;">Plusieurs mois</td><td style="text-align:left;">Une équipe complète</td><td style="text-align:left;">Des dizaines de milliers de dollars (serveurs, licences, équipe, sécurité)</td></tr></tbody></table><p>Ces chiffres sont des <strong>ordres de grandeur</strong> pour lancer la discussion, pas des prix à citer dans un rapport. Apprendre à trouver de vrais prix fait partie de la séance 3.</p></details><p><strong>Ce qu&#39;il faut retenir :</strong> « faire un site Web » peut vouloir dire des choses très différentes. Avant de juger si un projet est faisable, il faut savoir <strong>de quoi il est fait</strong>.</p><hr><h2 id="presentation-du-cours" tabindex="-1">Présentation du cours <a class="header-anchor" href="#presentation-du-cours" aria-label="Permalink to &quot;Présentation du cours&quot;">​</a></h2><ul><li><a href="./../../plan-cours/plan-de-cours">Plan de cours</a> et <a href="./../../plan-cours/calendrier">calendrier</a></li><li>Deux parties : <ul><li><strong>Partie 1 — HK29</strong> (séances 1 à 8) : évaluer la faisabilité technique d&#39;un projet.</li><li><strong>Partie 2 — HK33</strong> (séances 8 à 19) : collaborer à la conception d&#39;un projet Web.</li></ul></li><li>Un <strong>mandat de client</strong> servira de fil conducteur pour toute la session. Il sera présenté à la <strong>séance 2</strong>, en même temps que la formation des équipes (2 ou 3 personnes, les mêmes toute la session).</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Évaluation</th><th style="text-align:center;">Pondération</th><th style="text-align:left;">Travail</th></tr></thead><tbody><tr><td style="text-align:left;">Rapport de faisabilité technique — Évaluation technique</td><td style="text-align:center;">20 %</td><td style="text-align:left;">En équipe</td></tr><tr><td style="text-align:left;">Rapport de faisabilité technique — Proposition technique</td><td style="text-align:center;">20 %</td><td style="text-align:left;">En équipe</td></tr><tr><td style="text-align:left;">Collaborer à un projet Web agile — Évaluation du projet</td><td style="text-align:center;">20 %</td><td style="text-align:left;">En équipe</td></tr><tr><td style="text-align:left;">Collaborer à un projet Web agile — Proposition d&#39;un échéancier (synthèse)</td><td style="text-align:center;">40 %</td><td style="text-align:left;">Individuel</td></tr></tbody></table><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>À savoir dès maintenant</strong><br><ul class="list-disc pl-5"><li>Chaque jour de retard entraîne une pénalité de 10 %. Après 7 jours, la note est zéro.</li><li>Les deux premiers rapports sont aussi évalués sur la qualité du français.</li><li>L&#39;utilisation de l&#39;intelligence artificielle générative est encadrée : lisez la section du plan de cours à ce sujet.</li></ul></div><hr><h2 id="le-trajet-d-une-page-web" tabindex="-1">Le trajet d&#39;une page Web <a class="header-anchor" href="#le-trajet-d-une-page-web" aria-label="Permalink to &quot;Le trajet d&#39;une page Web&quot;">​</a></h2><p>Activité : <a href="./activite-casse-tete">Le trajet d&#39;une page Web (casse-tête)</a></p><p>Quand une cliente tape <code>bistro-exemple.ca</code> dans son téléphone, voici ce qui se passe :</p>',21)),(t(),o(c,null,{default:s(()=>[u(l,{id:"mermaid-367",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Appareil%20%2B%20navigateur%3Cbr%2F%3Ela%20cliente%20tape%20l'adresse%22%5D%20--%3E%7C%22%E2%91%A0%20O%C3%B9%20est%20ce%20site%3F%22%7C%20B%5B%22DNS%3Cbr%2F%3Enom%20de%20domaine%20%E2%86%92%20adresse%20IP%22%5D%0A%20%20%20%20B%20--%3E%7C%22%E2%91%A1%20Voici%20l'adresse%20IP%22%7C%20A%0A%20%20%20%20A%20--%3E%7C%22%E2%91%A2%20Demande%20la%20page%20(SSL%2FTLS)%22%7C%20C%5B%22CDN%3Cbr%2F%3E(optionnel)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22H%C3%A9bergement%3Cbr%2F%3Ele%20serveur%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Plateforme%3Cbr%2F%3EWordPress%2C%20Shopify%2C%20code%20maison%E2%80%A6%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22Contenus%3Cbr%2F%3Etextes%2C%20photos%2C%20menu%22%5D%0A%20%20%20%20E%20--%3E%7C%22%E2%91%A3%20Page%20HTML%2C%20CSS%2C%20JS%2C%20images%22%7C%20A%0A%20%20%20%20A%20-.-%3E%7C%22%E2%91%A4%20R%C3%A9server%20une%20table%22%7C%20G%5B%22Service%20externe%3Cbr%2F%3Er%C3%A9servation%2C%20paiement%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<ol><li>Le <strong>navigateur</strong> demande au <strong>DNS</strong> : « à quelle adresse se trouve <code>bistro-exemple.ca</code> ? ».</li><li>Le DNS répond avec l&#39;<strong>adresse IP</strong> du serveur. Le nom de domaine a été loué chez un <strong>registraire</strong>.</li><li>Le navigateur contacte le serveur par une <strong>connexion sécurisée</strong> (le cadenas, grâce au <strong>certificat SSL/TLS</strong>). Souvent, un <strong>CDN</strong> reçoit la demande en premier pour répondre plus vite.</li><li>L&#39;<strong>hébergement</strong> fait fonctionner la <strong>plateforme</strong>, qui assemble les <strong>contenus</strong> et renvoie la page.</li><li>Certaines fonctions ne sont pas dans le site lui-même : la réservation ou le paiement passent souvent par un <strong>service externe</strong>.</li></ol><p>Le <strong>courriel professionnel</strong> ne fait pas partie du trajet de la page, mais il utilise le même nom de domaine. Changer de fournisseur sans précaution peut le briser.</p><h3 id="demonstration-—-ce-site-ci" tabindex="-1">Démonstration — ce site-ci <a class="header-anchor" href="#demonstration-—-ce-site-ci" aria-label="Permalink to &quot;Démonstration — ce site-ci&quot;">​</a></h3><p>Le site du cours que vous consultez est <strong>hébergé gratuitement</strong> sur GitHub Pages. En direct, on regarde :</p><ul><li>ce qui est gratuit : l&#39;hébergement, le certificat, le déploiement automatique ;</li><li>ce qui ne l&#39;est pas : un nom de domaine personnalisé (p. ex. <code>mon-cours.ca</code>) coûterait quelques dizaines de dollars par année ;</li><li>les limites : ce type d&#39;hébergement ne permet ni base de données, ni paiement, ni compte utilisateur.</li></ul><p>Même un site « gratuit » a des <strong>limites techniques</strong> qui décident de ce qu&#39;il peut faire.</p><hr><h2 id="les-ressources-techniques-d-un-projet-web" tabindex="-1">Les ressources techniques d&#39;un projet Web <a class="header-anchor" href="#les-ressources-techniques-d-un-projet-web" aria-label="Permalink to &quot;Les ressources techniques d&#39;un projet Web&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Ressource</th><th style="text-align:left;">À quoi elle sert</th><th style="text-align:left;">Qui la fournit</th><th style="text-align:left;">Comment on la paie</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Nom de domaine</strong></td><td style="text-align:left;">L&#39;adresse du site (<code>.ca</code>, <code>.com</code>, <code>.quebec</code>…)</td><td style="text-align:left;">Un registraire</td><td style="text-align:left;">Chaque année</td></tr><tr><td style="text-align:left;"><strong>DNS</strong></td><td style="text-align:left;">Relier le nom de domaine au serveur et au courriel</td><td style="text-align:left;">Le registraire, l&#39;hébergeur ou un service comme Cloudflare</td><td style="text-align:left;">Souvent inclus</td></tr><tr><td style="text-align:left;"><strong>Hébergement</strong></td><td style="text-align:left;">Le serveur qui garde le site et le rend accessible</td><td style="text-align:left;">Un hébergeur ou la plateforme elle-même</td><td style="text-align:left;">Chaque mois ou chaque année</td></tr><tr><td style="text-align:left;"><strong>Certificat SSL/TLS</strong></td><td style="text-align:left;">Chiffrer la connexion (le cadenas)</td><td style="text-align:left;">L&#39;hébergeur, souvent gratuitement</td><td style="text-align:left;">Souvent inclus</td></tr><tr><td style="text-align:left;"><strong>Plateforme</strong></td><td style="text-align:left;">Construire et gérer le site</td><td style="text-align:left;">Logiciel libre (WordPress), service par abonnement (Wix, Shopify) ou développement sur mesure</td><td style="text-align:left;">Abonnement, licences ou développement</td></tr><tr><td style="text-align:left;"><strong>CDN</strong></td><td style="text-align:left;">Accélérer et protéger le site</td><td style="text-align:left;">Cloudflare, Fastly…</td><td style="text-align:left;">Gratuit à payant</td></tr><tr><td style="text-align:left;"><strong>Contenus</strong></td><td style="text-align:left;">Ce que le visiteur vient chercher</td><td style="text-align:left;">Le client, un photographe, un rédacteur…</td><td style="text-align:left;">Temps du client ou honoraires</td></tr><tr><td style="text-align:left;"><strong>Services externes</strong></td><td style="text-align:left;">Réservation, paiement, livraison, infolettre</td><td style="text-align:left;">Libro, OpenTable, Stripe…</td><td style="text-align:left;">Abonnement ou frais par transaction</td></tr><tr><td style="text-align:left;"><strong>Navigateurs et appareils</strong></td><td style="text-align:left;">Afficher le site</td><td style="text-align:left;">Le visiteur</td><td style="text-align:left;">— mais il faut <strong>tester</strong> sur plusieurs</td></tr></tbody></table><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Pièges fréquents</strong><br><ul class="list-disc pl-5"><li><strong>Confondre nom de domaine et hébergement.</strong> On peut louer le nom chez une entreprise et héberger le site chez une autre.</li><li><strong>Croire que « gratuit » veut dire sans coût.</strong> Les forfaits gratuits imposent souvent de la publicité, une adresse du genre <code>monresto.wixsite.com</code> ou des limites.</li><li><strong>Oublier les coûts récurrents.</strong> Le site se paie chaque année, pas seulement au lancement.</li><li><strong>Prendre le CDN pour l&#39;hébergeur.</strong> Si un outil indique « Cloudflare », le site est souvent hébergé ailleurs, derrière Cloudflare.</li><li><strong>Oublier le mobile.</strong> Pour un restaurant, une grande partie des visites se font sur téléphone.</li></ul></div><hr><h2 id="les-trois-sortes-de-contraintes" tabindex="-1">Les trois sortes de contraintes <a class="header-anchor" href="#les-trois-sortes-de-contraintes" aria-label="Permalink to &quot;Les trois sortes de contraintes&quot;">​</a></h2><p>Une <strong>contrainte</strong>, c&#39;est tout ce qui limite les choix possibles dans un projet.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Sorte</th><th style="text-align:left;">La question à se poser</th><th style="text-align:left;">Exemples</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Techniques</strong></td><td style="text-align:left;">Qu&#39;est-ce que la technologie permet ou impose ?</td><td style="text-align:left;">La plateforme ne permet pas la commande en ligne ; le site doit fonctionner sur les vieux téléphones ; le système de réservation actuel ne s&#39;intègre pas au site.</td></tr><tr><td style="text-align:left;"><strong>Organisationnelles</strong></td><td style="text-align:left;">Comment le client fonctionne-t-il ?</td><td style="text-align:left;">Personne n&#39;a le temps de mettre le menu à jour ; trois associés doivent approuver chaque décision ; le site doit respecter les lois sur la vie privée et la langue française.</td></tr><tr><td style="text-align:left;"><strong>De ressources</strong></td><td style="text-align:left;">De quoi dispose-t-on ?</td><td style="text-align:left;">Budget de 3 000 $ ; lancement dans 6 semaines ; aucune personne à l&#39;interne qui connaît WordPress.</td></tr></tbody></table><h3 id="retour-sur-l-accroche" tabindex="-1">Retour sur l&#39;accroche <a class="header-anchor" href="#retour-sur-l-accroche" aria-label="Permalink to &quot;Retour sur l&#39;accroche&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Restaurant</th><th style="text-align:left;">Une contrainte probable</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A</strong> — Café de quartier</td><td style="text-align:left;"><strong>Ressources</strong> : aucun budget, la propriétaire fait tout elle-même. C&#39;est pour ça qu&#39;elle a choisi Wix.</td></tr><tr><td style="text-align:left;"><strong>B</strong> — Bistro</td><td style="text-align:left;"><strong>Organisationnelle</strong> : le menu change chaque saison et c&#39;est le chef qui doit pouvoir le modifier, sans l&#39;aide d&#39;un programmeur.</td></tr><tr><td style="text-align:left;"><strong>C</strong> — Chaîne</td><td style="text-align:left;"><strong>Technique</strong> : la commande en ligne doit communiquer avec les caisses de 60 restaurants.</td></tr></tbody></table><p>Une même situation touche souvent <strong>plusieurs sortes</strong> de contraintes à la fois. À la séance 2, on classera toutes les contraintes du mandat du client.</p><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p>➡️ <a href="./../../labs/lab01-enquete-technique">Lab 01 — Enquête technique : comparer deux sites</a></p>',20))])}const v=r(g,[["render",p]]);export{q as __pageData,v as default};
